import { useState } from "react";

const flights = {
  AA123: { status: "On Time", gate: "B12", terminal: "2", boarding: "2:30 PM" },
  DL456: { status: "Delayed", gate: "C4", terminal: "1", boarding: "4:10 PM" },
  UA789: { status: "Boarding Soon", gate: "A8", terminal: "3", boarding: "6:45 PM" },
};

function App() {
  const [flight, setFlight] = useState("");

  const flightCode = flight.toUpperCase();
  const flightInfo = flights[flightCode];

  return (
    <div style={{
      backgroundColor: "#f4f6fb",
      minHeight: "100vh",
      padding: "30px",
      fontFamily: "Arial, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>✈️ Air Travel Assist</h1>

      <div style={{
        maxWidth: "450px",
        margin: "30px auto",
        backgroundColor: "white",
        padding: "24px",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.12)"
      }}>
        <h2>Enter Flight</h2>

        <input
          type="text"
          placeholder="Try AA123, DL456, or UA789"
          value={flight}
          onChange={(e) => setFlight(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            marginBottom: "20px",
            borderRadius: "6px",
            border: "1px solid #ccc"
          }}
        />

        {flightInfo ? (
          <>
            <h3>Flight Information</h3>
            <p><strong>Flight:</strong> {flightCode}</p>
            <p><strong>Status:</strong> {flightInfo.status}</p>

            <h3>Gate & Terminal</h3>
            <p><strong>Gate:</strong> {flightInfo.gate}</p>
            <p><strong>Terminal:</strong> {flightInfo.terminal}</p>

            <h3>Boarding</h3>
            <p><strong>Boarding Time:</strong> {flightInfo.boarding}</p>
          </>
        ) : (
          <p>Enter a sample flight number to view details.</p>
        )}
      </div>
    </div>
  );
}

export default App;
